// Parses the incoming conversion, normalises identifiers and builds a valid fbc.
// No hashing here - the Crypto nodes downstream do that.
const S = $('Settings').first().json;

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16);
}

// Accepts "user@example.com", ["user@example.com"] or [{ VALUE: "user@example.com" }] - CRMs differ.
const firstString = (v) => {
  if (Array.isArray(v)) {
    for (const item of v) {
      if (typeof item === 'string' && item.trim()) return item.trim();
      if (item && typeof item === 'object') {
        for (const nested of Object.values(item)) {
          if (typeof nested === 'string' && nested.trim()) return nested.trim();
        }
      }
    }
    return '';
  }
  if (v && typeof v === 'object') {
    for (const nested of Object.values(v)) {
      if (typeof nested === 'string' && nested.trim()) return nested.trim();
    }
    return '';
  }
  return String(v || '').trim();
};

const incoming = $input.first().json || {};
const body = incoming.body || incoming;
const now = Date.now();

const eventName = String(body.event_name || '').trim();
if (!eventName) throw new Error('event_name is missing: ' + JSON.stringify(body));

// ---- event_time -----------------------------------------------------------
// Accepts a unix timestamp, an ISO string, or "DD/MM/YYYY HH:mm:ss".
let eventTime = Number(body.event_time || 0);
let eventTimeSource = 'unix';
if (!Number.isFinite(eventTime) || eventTime <= 0) {
  const raw = String(body.event_time || '').trim();
  let d = null;
  const dmy = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2}):(\d{2})$/);
  if (dmy) {
    d = new Date(dmy[3] + '-' + dmy[2] + '-' + dmy[1] + 'T' + dmy[4] + ':' + dmy[5] + ':' + dmy[6] + 'Z');
    eventTimeSource = 'ddmmyyyy';
  } else if (raw) {
    d = new Date(raw);
    eventTimeSource = 'iso';
  }
  if (d && Number.isFinite(d.getTime())) eventTime = Math.floor(d.getTime() / 1000);
  else { eventTime = Math.floor(now / 1000); eventTimeSource = 'fallback_now'; }
}

// Meta rejects events older than 7 days and events in the future.
const nowSec = Math.floor(now / 1000);
const minSec = nowSec - Math.floor(6.5 * 24 * 3600);
const originalEventTime = eventTime;
const eventAgeDays = Math.round(((nowSec - eventTime) / 86400) * 10) / 10;
let staleClamped = false;
if (eventTime > nowSec) { eventTime = nowSec; eventTimeSource += '_clamped_future'; }
if (eventTime < minSec) { eventTime = minSec; eventTimeSource += '_clamped_7d_window'; staleClamped = true; }

// ---- identifiers ----------------------------------------------------------
// Meta's normalisation rules: lowercase, trim, strip punctuation and spaces.
const ud = body.user_data || {};
const normalizedEmail = String(firstString(ud.email || ud.em) || '').trim().toLowerCase();
const normalizedPhone = String(firstString(ud.phone || ud.ph) || '').replace(/[^0-9]/g, '');
const fbp = String(ud.fbp || '').trim();

const nameRule = (v) => String(v || '').trim().toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, '').trim();
const normalizedFirstName = nameRule(ud.first_name || ud.fn);
const normalizedLastName = nameRule(ud.last_name || ud.ln);
const normalizedCity = String(ud.city || ud.ct || '').trim().toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
const normalizedZip = String(ud.zip || ud.zp || '').trim().toLowerCase().replace(/\s+/g, '');
const normalizedCountry = String(ud.country || '').trim().toLowerCase().slice(0, 2);

// Sent unhashed, exactly as Meta expects.
const externalId = String(firstString(ud.external_id) || '').trim();
const rawIp = String(ud.client_ip_address || '').trim();
// Only a public client address helps; a private or server address hurts matching.
const isIp = /^(\d{1,3}\.){3}\d{1,3}$/.test(rawIp) || /^[0-9a-f:]+:[0-9a-f:]+$/i.test(rawIp);
const clientIp = isIp && !/^(10\.|127\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|0\.)/.test(rawIp) ? rawIp : '';
const clientUserAgent = String(ud.client_user_agent || '').trim();

// FBC: Meta expects fb.<subdomainIndex>.<creationTimeMs>.<fbclid>. A bare fbclid
// is accepted by the API but silently ignored for matching, so wrap it.
const rawFbc = String(ud.fbc || ud.fbclid || body.fbclid || '').trim();
let fbc = '';
let fbcMode = 'none';
if (rawFbc) {
  if (/^fb\.\d+\.\d{10,}\..+/.test(rawFbc)) { fbc = rawFbc; fbcMode = 'already_valid'; }
  else { fbc = 'fb.1.' + originalEventTime * 1000 + '.' + rawFbc; fbcMode = 'wrapped_from_raw_fbclid'; }
}

const customData = body.custom_data && typeof body.custom_data === 'object' ? body.custom_data : {};
const actionSource = String(body.action_source || 'website').trim() || 'website';
const eventSourceUrl = String(body.event_source_url || '').trim() || String(S.defaultEventSourceUrl || '').trim();

// Deliberately excludes event_time: a CRM retrying with a drifting timestamp is
// still the same conversion.
const orderId = String(customData.order_id || customData.deal_id || body.order_id || '').trim();
const dedupeBasis = JSON.stringify({ e: eventName, o: orderId, em: normalizedEmail, ph: normalizedPhone });
const dedupeKey = fnv1a(dedupeBasis) + '_' + dedupeBasis.length;

return [{ json: {
  dedupeKey,
  orderId,
  eventName,
  eventTime,
  eventTimeSource,
  eventAgeDays,
  staleClamped,
  normalizedEmail,
  normalizedPhone,
  normalizedFirstName,
  normalizedLastName,
  normalizedCity,
  normalizedZip,
  normalizedCountry,
  externalId,
  clientIp,
  clientUserAgent,
  fbc,
  fbp,
  fbcMode,
  customData,
  actionSource,
  eventSourceUrl,
  testEventCode: String(body.test_event_code || '').trim(),
  eventId: eventName.toLowerCase().replace(/[^a-z0-9]+/g, '_') + '_' + (orderId || dedupeKey),
} }];

// Assembles the Meta payload. The Data Table insert replaces the item, so the
// parsed fields are read back from the Parse node; only hashes come from input.
const p = $('Parse and Normalize').first().json;
const h = $input.first().json;

const user_data = {};
if (p.fbc) user_data.fbc = p.fbc;
if (p.fbp) user_data.fbp = p.fbp;
// Hashed identifiers, in Meta's order of matching value.
if (p.normalizedEmail) user_data.em = [h.hashedEmail];
if (p.normalizedPhone) user_data.ph = [h.hashedPhone];
if (p.normalizedFirstName) user_data.fn = [h.hashedFirstName];
if (p.normalizedLastName) user_data.ln = [h.hashedLastName];
if (p.normalizedCity) user_data.ct = [h.hashedCity];
if (p.normalizedZip) user_data.zp = [h.hashedZip];
if (p.normalizedCountry) user_data.country = [h.hashedCountry];
// These three are sent as-is; Meta does not want them hashed.
if (p.externalId) user_data.external_id = [p.externalId];
if (p.clientIp) user_data.client_ip_address = p.clientIp;
if (p.clientUserAgent) user_data.client_user_agent = p.clientUserAgent;

if (!user_data.fbc && !user_data.fbp && !user_data.em && !user_data.ph && !user_data.external_id) {
  throw new Error('No usable identifiers for Meta: send at least an email, phone, external_id, fbc or fbp');
}

const requestBody = { data: [{
  event_name: p.eventName,
  event_time: p.eventTime,
  event_id: p.eventId,
  action_source: p.actionSource,
  event_source_url: p.eventSourceUrl,
  user_data,
  custom_data: p.customData,
}] };

// Routes the event to Meta's Test Events tool instead of production reporting.
if (p.testEventCode) requestBody.test_event_code = p.testEventCode;

return [{ json: { orderId: p.orderId, dedupeKey: p.dedupeKey, requestBody, summary: {
  identifiers: Object.keys(user_data),
  identifierCount: Object.keys(user_data).length,
  fbcMode: p.fbcMode, staleClamped: p.staleClamped, eventAgeDays: p.eventAgeDays,
  eventTimeSource: p.eventTimeSource } }, }];

// Meta answers HTTP 200 even when it drops an event, so inspect the body.
const payload = $input.first().json || {};
const body = payload.body || payload;

if (body.error) throw new Error('Meta Graph API error: ' + JSON.stringify(body.error));

const received = Number(body.events_received || 0);
if (!Number.isFinite(received) || received < 1) {
  throw new Error('Meta received no events: ' + JSON.stringify(body));
}

const source = $('Build Meta Payload').first().json || {};
return [{ json: {
  sent: true,
  eventsReceived: received,
  orderId: source.orderId || '',
  summary: source.summary || {},
  sentAt: new Date().toISOString(),
} }];
